CREATE TABLE integration_settings(tenant_id text NOT NULL REFERENCES tenants(id),kind text NOT NULL,config jsonb NOT NULL DEFAULT '{}',revision integer NOT NULL DEFAULT 1,PRIMARY KEY(tenant_id,kind));
CREATE TABLE gemini_pool_projects(tenant_id text NOT NULL REFERENCES tenants(id),id text NOT NULL,label text NOT NULL,daily_limit integer NOT NULL CHECK(daily_limit>0),max_concurrent integer NOT NULL DEFAULT 2 CHECK(max_concurrent>0),cooldown_until timestamptz,exhausted_day text,PRIMARY KEY(tenant_id,id));
CREATE TABLE gemini_pool_keys(tenant_id text NOT NULL,id text NOT NULL,connection_id text NOT NULL,project_id text NOT NULL,key_hash text NOT NULL,name text NOT NULL,masked text NOT NULL,daily_limit integer NOT NULL CHECK(daily_limit>0),status text NOT NULL DEFAULT 'active',last_error_code text,last_tested_at timestamptz,PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,key_hash),FOREIGN KEY(tenant_id,connection_id) REFERENCES connections(tenant_id,id),FOREIGN KEY(tenant_id,project_id) REFERENCES gemini_pool_projects(tenant_id,id));
CREATE TABLE gemini_pool_attempts(id text PRIMARY KEY,tenant_id text NOT NULL,key_id text NOT NULL,project_id text NOT NULL,budget_day text NOT NULL,model text NOT NULL,status text NOT NULL DEFAULT 'reserved',error_code text,reserved_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval '4 minutes',FOREIGN KEY(tenant_id,key_id) REFERENCES gemini_pool_keys(tenant_id,id),FOREIGN KEY(tenant_id,project_id) REFERENCES gemini_pool_projects(tenant_id,id));
CREATE INDEX gemini_pool_budget ON gemini_pool_attempts(tenant_id,project_id,budget_day);
CREATE TABLE google_oauth_states(state_hash text PRIMARY KEY,tenant_id text NOT NULL,actor_id text NOT NULL,connection_id text NOT NULL,nonce_hash text NOT NULL,redirect_uri text NOT NULL,expires_at timestamptz NOT NULL,FOREIGN KEY(tenant_id,actor_id) REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,connection_id) REFERENCES connections(tenant_id,id));
CREATE TABLE publishing_media(id text PRIMARY KEY,tenant_id text NOT NULL,item_id text NOT NULL,revision integer NOT NULL,sha256 text NOT NULL,connection_id text NOT NULL,folder_id text NOT NULL,file_id text,permission_id text,status text NOT NULL DEFAULT 'prepared',public_url text,mime_type text NOT NULL,byte_size bigint NOT NULL,expires_at timestamptz NOT NULL,error_code text,lease_owner text,lease_expires_at timestamptz,fencing_token bigint NOT NULL DEFAULT 0,UNIQUE(tenant_id,item_id,revision,sha256,connection_id),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,item_id) REFERENCES content_items(tenant_id,id),FOREIGN KEY(tenant_id,connection_id) REFERENCES connections(tenant_id,id));
ALTER TABLE publishing_intents ADD COLUMN media_id text;
ALTER TABLE publishing_intents ADD COLUMN next_attempt_at timestamptz;
ALTER TABLE publishing_intents ADD FOREIGN KEY(tenant_id,media_id) REFERENCES publishing_media(tenant_id,id);
CREATE TABLE provider_dispatch_lanes(tenant_id text NOT NULL,connection_id text NOT NULL,next_submit_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,connection_id),FOREIGN KEY(tenant_id,connection_id) REFERENCES connections(tenant_id,id));
